local P,RS,W,CAM,LP,CG,UIS,VIM,TS,HS,ST = game:GetService("Players"),game:GetService("RunService"),game:GetService("Workspace"),game:GetService("Workspace").CurrentCamera,game:GetService("Players").LocalPlayer,game:GetService("CoreGui"),game:GetService("UserInputService"),game:GetService("VirtualInputManager"),game:GetService("TweenService"),game:GetService("HttpService"),game:GetService("Stats")
local S={Enabled=true,ColorVisible=Color3.fromRGB(0,255,0),ColorBehindWall=Color3.fromRGB(255,0,0),ShowBox=true,ShowName=true,ShowDistance=true,ShowHealth=true,ShowTracer=false,ShowChams=false,ShowSkeleton=false,ShowBots=true,TeamCheck=false,WallCheckRaycast=true,MaxDistance=1000,UseTeamColors=true,TB_Enabled=false,TB_Delay=0.05,TB_TeamCheck=true,TB_WallCheck=true,TB_Bind=Enum.KeyCode.Z,AB_Enabled=false,AB_FOV=150,AB_Smooth=0.2,AB_Bind=Enum.KeyCode.X}
local function saveCfg() if not writefile then return end local d={} for k,v in pairs(S) do if typeof(v)=="Color3" then d[k]={math.floor(v.R*255),math.floor(v.G*255),math.floor(v.B*255)} elseif typeof(v)=="EnumItem" then d[k]=v.Name else d[k]=v end end pcall(function() writefile("esp_cfg.json",HS:JSONEncode(d)) end) end
local function loadCfg() if not (isfile and isfile("esp_cfg.json")) then return end pcall(function() local d=HS:JSONDecode(readfile("esp_cfg.json")) for k,v in pairs(d) do if type(v)=="table" and #v==3 then S[k]=Color3.fromRGB(v[1],v[2],v[3]) elseif k=="TB_Bind" or k=="AB_Bind" then S[k]=Enum.KeyCode[v] or S[k] else S[k]=v end end end) end
loadCfg()
local function vis(wp) if not S.WallCheckRaycast then return true end local pr=RaycastParams.new() pr.FilterType=Enum.RaycastFilterType.Exclude local ex={CAM} if LP.Character then table.insert(ex,LP.Character) end for _,p in ipairs(P:GetPlayers()) do if p.Character then table.insert(ex,p.Character) end end pr.FilterDescendantsInstances=ex local r=W:Raycast(CAM.CFrame.Position,wp-CAM.CFrame.Position,pr) if not r then return true end local m=r.Instance and r.Instance:FindFirstAncestorOfClass("Model") if m and m:FindFirstChildOfClass("Humanoid") then return true end return false end
local function pickCol(info,vs) if info.teamColor and S.UseTeamColors and vs then return info.teamColor end return vs and S.ColorVisible or S.ColorBehindWall end
local function w2v(p) local sp,on=CAM:WorldToViewportPoint(p) return Vector2.new(sp.X,sp.Y),sp.Z,on end
local function nD(c,pr) local ok,d=pcall(function() return Drawing.new(c) end) if not ok or not d then return nil end for k,v in pairs(pr or {}) do pcall(function() d[k]=v end) end return d end
local DR={}
local R15={{"Head","UpperTorso"},{"UpperTorso","LowerTorso"},{"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"LeftLowerArm","LeftHand"},{"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"RightLowerArm","RightHand"},{"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},{"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"}}
local R6={{"Head","Torso"},{"Torso","Left Arm"},{"Torso","Right Arm"},{"Torso","Left Leg"},{"Torso","Right Leg"}}
local function createV(m) local d={box=S.ShowBox and nD("Square",{Thickness=1,Filled=false,Visible=false}) or nil,name=S.ShowName and nD("Text",{Center=true,Outline=true,Size=14,Font=2,Visible=false}) or nil,dist=S.ShowDistance and nD("Text",{Center=true,Outline=true,Size=12,Font=2,Visible=false}) or nil,hpBg=S.ShowHealth and nD("Square",{Thickness=1,Filled=true,Visible=false}) or nil,hpFg=S.ShowHealth and nD("Square",{Thickness=0,Filled=true,Visible=false}) or nil,tracer=S.ShowTracer and nD("Line",{Thickness=1,Visible=false}) or nil,bones={},cham=nil} if S.ShowChams then local hl=Instance.new("Highlight") hl.Name="ESP_Cham" hl.FillTransparency=0.5 hl.OutlineTransparency=0 hl.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop hl.Adornee=m hl.Parent=CG d.cham=hl end if S.ShowSkeleton then local bl=m:FindFirstChild("UpperTorso") and R15 or R6 for i=1,#bl do local l=nD("Line",{Thickness=1,Visible=false}) if l then d.bones[i]=l end end end DR[m]=d end
local function hideV(d) if d.box then d.box.Visible=false end if d.name then d.name.Visible=false end if d.dist then d.dist.Visible=false end if d.hpBg then d.hpBg.Visible=false end if d.hpFg then d.hpFg.Visible=false end if d.tracer then d.tracer.Visible=false end if d.cham then d.cham.Enabled=false end for _,l in pairs(d.bones) do l.Visible=false end end
local function destroyV(m) local d=DR[m] if not d then return end for _,v in pairs(d) do if type(v)=="table" then for _,l in pairs(v) do pcall(function() l:Remove() end) end elseif v and v.ClassName=="Highlight" then pcall(function() v:Destroy() end) elseif v then pcall(function() v:Remove() end) end end DR[m]=nil end
local function clearAll() for m in pairs(DR) do destroyV(m) end end
local function getAimTgt() local cls=nil local md=S.AB_FOV local vp=CAM.ViewportSize local cx,cy=vp.X/2,vp.Y/2 for _,p in ipairs(P:GetPlayers()) do if p~=LP and p.Character and p.Character:FindFirstChild("Head") then local h=p.Character:FindFirstChildOfClass("Humanoid") if h and h.Health>0 and (not S.TB_TeamCheck or p.Team~=LP.Team) then local sp,on=CAM:WorldToViewportPoint(p.Character.Head.Position) if on then local d=(Vector2.new(sp.X,sp.Y)-Vector2.new(cx,cy)).Magnitude if d<md then md=d cls=p.Character.Head end end end end end return cls end
local lastC=0
local function tbLog() if not S.TB_Enabled or tick()-lastC<S.TB_Delay then return end local vp=CAM.ViewportSize local cx,cy=vp.X/2,vp.Y/2 local ur=CAM:ViewportPointToRay(cx,cy) local pr=RaycastParams.new() pr.FilterType=Enum.RaycastFilterType.Exclude local ex={CAM} if LP.Character then table.insert(ex,LP.Character) end pr.FilterDescendantsInstances=ex local res=W:Raycast(ur.Origin,ur.Direction*2000,pr) if res and res.Instance then local hm=res.Instance:FindFirstAncestorOfClass("Model") if hm then local h=hm:FindFirstChildOfClass("Humanoid") local plr=P:GetPlayerFromCharacter(hm) if h and h.Health>0 then local isE=true if S.TB_TeamCheck and plr and plr.Team==LP.Team then isE=false end if isE then lastC=tick() pcall(function() VIM:SendMouseButtonEvent(cx,cy,0,true,game,1) task.wait(0.01) VIM:SendMouseButtonEvent(cx,cy,0,false,game,1) end) local t=LP.Character and LP.Character:FindFirstChildOfClass("Tool") if t then t:Activate() end end end end end end
local function abLog() if not S.AB_Enabled then return end local tgt=getAimTgt() if tgt and vis(tgt.Position) then local cf=CFrame.new(CAM.CFrame.Position,tgt.Position) if S.AB_Smooth>0 then CAM.CFrame=CAM.CFrame:Lerp(cf,S.AB_Smooth) else CAM.CFrame=cf end end end
local function updESP() local ct={} for _,p in ipairs(P:GetPlayers()) do if p~=LP and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then if not S.TeamCheck or p.Team~=LP.Team then local tc=nil if S.UseTeamColors and p.Team then tc=p.Team.TeamColor.Color end ct[p.Character]={name=p.Name,teamColor=tc} end end end if S.ShowBots then for _,o in ipairs(W:GetDescendants()) do if o:IsA("Model") and o:FindFirstChildOfClass("Humanoid") and o:FindFirstChild("HumanoidRootPart") and not P:GetPlayerFromCharacter(o) then local ok,sz=pcall(function() return o:GetExtentsSize() end) if ok and sz.Y<15 then ct[o]={name=o.Name,teamColor=nil} end end end end for m in pairs(DR) do if not ct[m] or not m.Parent then destroyV(m) end end local vp=CAM.ViewportSize local cb=Vector2.new(vp.X/2,vp.Y) for m,info in pairs(ct) do if not DR[m] then createV(m) end local d=DR[m] local hrp=m:FindFirstChild("HumanoidRootPart") local head=m:FindFirstChild("Head") if not hrp or not head then hideV(d) continue end local rp=hrp.Position local di=(CAM.CFrame.Position-rp).Magnitude if di>S.MaxDistance or not m.Parent then hideV(d) continue end local visible=vis(rp) local c=pickCol(info,visible) local sp,dp,on=w2v(rp) local hsp,hdp=w2v(head.Position+Vector3.new(0,1,0)) local fsp,fdp=w2v(hrp.Position-Vector3.new(0,3,0)) if not on or dp<=0 or hdp<=0 or fdp<=0 then hideV(d) continue end local h=math.abs(fsp.Y-hsp.Y) local w=h*0.6 if h<5 or h>800 then hideV(d) continue end local x=sp.X-(w/2) local y=hsp.Y if d.box then d.box.Visible=S.ShowBox d.box.Color=c d.box.Size=Vector2.new(w,h) d.box.Position=Vector2.new(x,y) end if d.name then d.name.Visible=S.ShowName d.name.Text=info.name d.name.Color=c d.name.Position=Vector2.new(sp.X,y-18) end if d.dist then d.dist.Visible=S.ShowDistance d.dist.Text=string.format("[%d]",math.floor(di)) d.dist.Color=c d.dist.Position=Vector2.new(sp.X,y+h+2) end local hum=m:FindFirstChildOfClass("Humanoid") if d.hpBg and d.hpFg and hum and S.ShowHealth then local pct=math.clamp(hum.Health/hum.MaxHealth,0,1) local bw=3 local bx=x-6 d.hpBg.Visible=true d.hpBg.Size=Vector2.new(bw,h) d.hpBg.Position=Vector2.new(bx,y) d.hpBg.Color=Color3.fromRGB(0,0,0) local hc=Color3.fromRGB(0,255,0) if pct<0.3 then hc=Color3.fromRGB(255,0,0) elseif pct<0.6 then hc=Color3.fromRGB(255,255,0) end d.hpFg.Visible=true d.hpFg.Size=Vector2.new(bw,h*pct) d.hpFg.Position=Vector2.new(bx,y+h*(1-pct)) d.hpFg.Color=hc else if d.hpBg then d.hpBg.Visible=false end if d.hpFg then d.hpFg.Visible=false end end if S.ShowTracer then if not d.tracer then d.tracer=nD("Line",{Thickness=1,Visible=false}) end if d.tracer then d.tracer.Visible=true d.tracer.Color=c d.tracer.From=cb d.tracer.To=Vector2.new(sp.X,y+h) end elseif d.tracer then d.tracer.Visible=false end if d.cham then d.cham.Enabled=S.ShowChams d.cham.FillColor=c d.cham.OutlineColor=c end if S.ShowSkeleton and d.bones then local bl=m:FindFirstChild("UpperTorso") and R15 or R6 for i,pr in ipairs(bl) do local l=d.bones[i] if l then local a=m:FindFirstChild(pr[1]) local b=m:FindFirstChild(pr[2]) if a and b and a:IsA("BasePart") and b:IsA("BasePart") then local pa,da=w2v(a.Position) local pb,db=w2v(b.Position) if da>0 and db>0 then l.Visible=true l.From=pa l.To=pb l.Color=c else l.Visible=false end else l.Visible=false end end end end end end
local frames=0 local lastT=tick()
