local function addSl(txt,mn,mx,def,cb) local row=mk("Frame",{Size=UDim2.new(1,0,0,46),BackgroundTransparency=1,LayoutOrder=nO(),Parent=scr}) local lb=mk("TextLabel",{Size=UDim2.new(1,-8,0,18),Position=UDim2.new(0,4,0,0),BackgroundTransparency=1,Text=txt..": "..def,TextColor3=Color3.fromRGB(220,220,220),Font=Enum.Font.Gotham,TextSize=12,TextXAlignment=Enum.TextXAlignment.Left,Parent=row}) local bar=mk("Frame",{Size=UDim2.new(1,-8,0,6),Position=UDim2.new(0,4,0,26),BackgroundColor3=Color3.fromRGB(60,60,70),BorderSizePixel=0,Parent=row}) mk("UICorner",{CornerRadius=UDim.new(1,0)},bar) local fil=mk("Frame",{Size=UDim2.new((def-mn)/(mx-mn),0,1,0),BackgroundColor3=Color3.fromRGB(0,180,255),BorderSizePixel=0,Parent=bar}) mk("UICorner",{CornerRadius=UDim.new(1,0)},fil) local kn=mk("Frame",{Size=UDim2.new(0,12,0,12),AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.new(fil.Size.X.Scale,0,0.5,0),BackgroundColor3=Color3.fromRGB(255,255,255),BorderSizePixel=0,Parent=bar}) mk("UICorner",{CornerRadius=UDim.new(1,0)},kn) local dr=false local function up(x) local r=math.clamp((x-bar.AbsolutePosition.X)/bar.AbsoluteSize.X,0,1) local v=math.floor(mn+(mx-mn)*r+0.5) fil.Size=UDim2.new(r,0,1,0) kn.Position=UDim2.new(r,0,0.5,0) lb.Text=txt..": "..v cb(v) end bar.InputBegan:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dr=true up(i.Position.X) end end) UIS.InputChanged:Connect(function(i) if dr and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch) then up(i.Position.X) end end) UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dr=false end end) end
local function addSep(txt) local row=mk("Frame",{Size=UDim2.new(1,0,0,20),BackgroundTransparency=1,LayoutOrder=nO(),Parent=scr}) mk("TextLabel",{Size=UDim2.new(1,-8,1,0),Position=UDim2.new(0,4,0,0),BackgroundTransparency=1,Text="── "..txt.." ──",TextColor3=Color3.fromRGB(120,140,170),Font=Enum.Font.GothamBold,TextSize=11,TextXAlignment=Enum.TextXAlignment.Left,Parent=row}) end
addSep("ESP") addTg("ESP вкл",S.Enabled,function(v) S.Enabled=v if not v then clearAll() end end) addCl("Цвет видимых",S.ColorVisible,function(c) S.ColorVisible=c end) addCl("Цвет за стеной",S.ColorBehindWall,function(c) S.ColorBehindWall=c end) addTg("Цвета команд",S.UseTeamColors,function(v) S.UseTeamColors=v end) addTg("Бокс",S.ShowBox,function(v) S.ShowBox=v clearAll() end) addTg("Имя",S.ShowName,function(v) S.ShowName=v clearAll() end) addTg("Дистанция",S.ShowDistance,function(v) S.ShowDistance=v clearAll() end) addTg("HP",S.ShowHealth,function(v) S.ShowHealth=v clearAll() end) addTg("Трейсер",S.ShowTracer,function(v) S.ShowTracer=v clearAll() end) addTg("Chams",S.ShowChams,function(v) S.ShowChams=v clearAll() end) addTg("Скелет",S.ShowSkeleton,function(v) S.ShowSkeleton=v clearAll() end) addTg("Ботов",S.ShowBots,function(v) S.ShowBots=v end) addTg("Только враги (ESP)",S.TeamCheck,function(v) S.TeamCheck=v end) addTg("Проверка стен (ESP)",S.WallCheckRaycast,function(v) S.WallCheckRaycast=v end) addSl("Макс. дистанция",50,3000,S.MaxDistance,function(v) S.MaxDistance=v end)
addSep("AIMBOT") local abTg=mk("TextButton",{Size=UDim2.new(1,-8,0,26),Position=UDim2.new(0,4,0,0),BackgroundColor3=S.AB_Enabled and Color3.fromRGB(0,180,60) or Color3.fromRGB(60,60,80),Text=S.AB_Enabled and "AIMBOT: ON" or "AIMBOT: OFF",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,BorderSizePixel=0,Parent=scr,LayoutOrder=nO()}) mk("UICorner",{CornerRadius=UDim.new(0,4)},abTg) abTg.MouseButton1Click:Connect(function() S.AB_Enabled=not S.AB_Enabled abTg.BackgroundColor3=S.AB_Enabled and Color3.fromRGB(0,180,60) or Color3.fromRGB(60,60,80) abTg.Text=S.AB_Enabled and "AIMBOT: ON" or "AIMBOT: OFF" showToast(S.AB_Enabled and "Aimbot ON" or "Aimbot OFF") end) addSl("Плавность",1,100,S.AB_Smooth*100,function(v) S.AB_Smooth=v/100 end) addSl("Радиус FOV",50,500,S.AB_FOV,function(v) S.AB_FOV=v end)
addSep("TRIGGERBOT") local tbTg=mk("TextButton",{Size=UDim2.new(1,-8,0,26),Position=UDim2.new(0,4,0,0),BackgroundColor3=S.TB_Enabled and Color3.fromRGB(0,180,60) or Color3.fromRGB(60,60,80),Text=S.T
